'use strict';
function sceneImage(name,attributes=''){
 const item=window.SCENE_IMAGES[name];
 if(!item)return `<img src="assets/${name}.webp" ${attributes} decoding="async">`;
 const sources=new Map(item.variants.map(([label,width])=>[width,`assets/${name}-${label}.webp`]));sources.set(item.width,`assets/${name}.webp`);
 const width=attributes.includes('scene-bg')?'100vw':attributes.includes('banner')?'(max-width:650px) 45vw, 25vw':'(max-width:650px) 180px, 260px';
 return `<img src="assets/${name}-small.webp" srcset="${[...sources].sort((a,b)=>a[0]-b[0]).map(([w,url])=>url+' '+w+'w').join(',')}" sizes="${width}" width="${item.width}" height="${item.height}" ${attributes} decoding="async">`;
}
function sceneContent(content){return content.replace(/<img\s+([^>]*?)src="assets\/([^"/]+)\.webp"([^>]*)>/g,(_,before,name,after)=>sceneImage(name,before+after))}
const warmedImages=new Set();let warmGeneration=0;
function warmNextScene(){
 const generation=++warmGeneration,connection=navigator.connection;
 if(connection?.saveData||/^(slow-)?2g$/.test(connection?.effectiveType||''))return;
 const idle=window.requestIdleCallback||(fn=>setTimeout(fn,800));
 idle(async()=>{
  if(generation!==warmGeneration||document.hidden)return;
  const routes={gryffindor:['boggart-v3','room','patronus'],hufflepuff:['greenhouse-v3','snare-v3','greenhouse-v3'],ravenclaw:['ravenclaw','ravenclaw-v3','ravenclaw'],slytherin:['slytherin','slytherin','mirror-v3']};
  let names=[];
  if(state.scene==='home'||state.scene==='letter')names=['hall'];
  if(state.scene==='arrival'||state.scene==='spells')names=[routes[H().id][0]];
  if(state.scene==='branch')names=[state.storyStep<2?routes[H().id][state.storyStep+1]:'hall'];
  for(const name of names){if(generation!==warmGeneration)return;const item=window.SCENE_IMAGES[name];if(!item)continue;const width=innerWidth*Math.min(devicePixelRatio||1,2),label=width<=480?'small':width<=960?'medium':'';const url=`assets/${name}${label?'-'+label:''}.webp`;if(warmedImages.has(url))continue;warmedImages.add(url);const image=new Image();image.fetchPriority='low';image.decoding='async';image.src=url;try{await image.decode()}catch{warmedImages.delete(url)}}
 },{timeout:2500});
}
document.addEventListener('error',event=>{
 const image=event.target;if(!(image instanceof HTMLImageElement)||!image.closest('#app'))return;
 if(image.dataset.retried){image.style.visibility='hidden';return}image.dataset.retried='true';
 if(!image.classList.contains('scene-bg')){image.style.visibility='hidden';return}
 const stage=image.closest('.stage');if(!stage||stage.querySelector('.scene-retry'))return;
 const button=document.createElement('button');button.className='scene-retry';button.textContent='场景图片未加载 · 轻触重试';button.setAttribute('aria-label','重试场景图片，当前关卡可以继续操作');stage.appendChild(button);
 button.onclick=()=>{button.disabled=true;image.removeAttribute('srcset');const source=new URL(image.currentSrc||image.src,location.href);source.searchParams.set('retry',Date.now());image.onload=()=>{image.style.visibility='';button.remove()};image.onerror=()=>{button.disabled=false;button.textContent='图片暂不可用 · 仍可继续冒险'};image.src=source.href};
},true);
document.addEventListener('DOMContentLoaded',()=>{
 const originalGo=go;go=function(scene){originalGo(scene);warmNextScene()};
 const screen=document.querySelector('#film-screen'),reader=document.querySelector('#reader-mount');
 function watchPlayer(container){let timer=0;new MutationObserver(()=>{clearTimeout(timer);const iframe=container.querySelector('iframe');if(!iframe)return;timer=setTimeout(()=>{if(!iframe.isConnected||container.nextElementSibling?.classList.contains('external-wait'))return;const note=document.createElement('p');note.className='external-wait';note.textContent=container===screen?'若画面仍未出现，可在下方官方频道打开；也可以直接回到冒险。':'书页若未显示，请使用上方“在新窗口阅读”，无需等待即可继续冒险。';container.insertAdjacentElement('afterend',note)},6500);iframe.addEventListener('load',()=>clearTimeout(timer),{once:true})}).observe(container,{childList:true})}
 watchPlayer(screen);watchPlayer(reader);document.querySelector('#library-dialog').addEventListener('close',()=>document.querySelectorAll('.external-wait').forEach(n=>n.remove()));
});

