function frame(img,cls,content,n=0){app.innerHTML=`<section class="stage ${cls}" id="stage">${sceneImage(img,'class="scene-bg" alt="" fetchpriority="high"')}<div class="shade ${cls.includes('center')?'center-shade':''}"></div><div class="fog"></div>${sceneContent(content)}<div class="scene-foot"><span>一场只为你而来的魔法 · 21</span><div class="progress" aria-label="冒险进度 ${n}/6">${[1,2,3,4,5,6].map(i=>`<i class="${i<=n?'on':''}"></i>`).join('')}</div><button class="ghost credit-mini" data-about>非官方生日同人 · 图片来源</button></div></section>`;app.querySelectorAll('[data-about]').forEach(b=>b.onclick=()=>openDialog('#about-dialog'));}
