function home(){frame('castle','home',`<div class="hero-copy"><div class="eyebrow">YOUR TWENTY-FIRST CHAPTER</div><h1>今晚，<br>魔法<em>因你而醒。</em></h1><p>霍格沃茨的灯已经亮起。<br>卢娜等你一起，走进二十一岁的故事。</p><div class="actions"><button class="gold-button" id="begin-music">♫ 带着音乐，拆开来信 ↗</button><button class="under-button" id="begin-quiet">安静地进入</button></div><p class="small-note">戴上耳机，轻触发光的地方。故事会回应你。</p>${saved&&saved.house?'<button class="under-button" id="continue">继续上次的冒险 →</button>':''}</div><div class="hero-date">21<small>HAPPY BIRTHDAY</small></div><div class="luna-polaroid"><img src="assets/luna.webp" alt="卢娜在邓布利多军训练中施放守护神的电影剧照"><span>我在城堡里等你。</span><small>LUNA LOVEGOOD</small></div>`);$('#begin-music').onclick=()=>fresh(true);$('#begin-quiet').onclick=()=>fresh(false);if($('#continue'))$('#continue').onclick=()=>{state={...initial(),...saved,name:String(saved.name||'').slice(0,24),found:saved.found.filter(i=>Number.isInteger(i)&&i>=0&&i<3)};if(!houses.some(h=>h.id===state.house)){fresh();return}go(state.finished?'final':state.scene==='home'?'arrival':state.scene)};}
function letter(open=false){frame('castle','letter-stage center',open?`<div class="letter-paper"><div class="letter-stamp">HOGWARTS · A PRIVATE INVITATION</div><h1>致今天二十一岁的你：</h1><p>这不是迟到的入学通知。<br>是城堡为你留的一晚，是朋友为你藏的惊喜。</p><p>带上一点好奇。卢娜会在大礼堂等你。<br>今夜，要用你自己的魔法，找到那份祝福。</p><label for="name">在信上留下你的名字或昵称（可不填）</label><input id="name" class="name-input" maxlength="24" autocomplete="off" placeholder="今夜的主角" value="${esc(state.name)}"><button class="gold-button" id="enter-hall">推开大礼堂的门 →</button></div>`:`<div class="owl-letter"><div class="eyebrow">THE OWL HAS FOUND YOU</div><h1 class="title">猫头鹰，终于找到你了。</h1><button class="envelope" id="break-seal" aria-label="打开信封上的火漆封印"><span class="seal">H</span><span>致 · 二十一岁的你</span></button><p class="subtitle">轻触火漆，把这个夜晚拆开。</p></div>`,1);if(!open)$('#break-seal').onclick=()=>{music.chime();burst(innerWidth/2,innerHeight/2);letter(true)};else{$('#enter-hall').onclick=()=>{state.name=$('#name').value.trim();go('sorting')};$('#name').onkeydown=e=>{if(e.key==='Enter')$('#enter-hall').click()}}}
