function keys(){let selected='',busy=false;const choices=[{id:'bronze',x:17,y:35,label:'铜色圆环钥匙'},{id:'silver',x:67,y:13,label:'银色圆环钥匙'},{id:'long',x:44,y:41,label:'银色菱形钥匙'}];frame('room','challenge-stage center',`${challengeHeading('02 · ACCIO','让远处的惊喜，飞向你。','锁孔旁画着提示：银色、圆环、双齿。选中相符的钥匙，再施放飞来咒。')}<div class="arena">${choices.map(k=>`<div class="flying-key" data-key="${k.id}" style="left:${k.x}%;top:${k.y}%;animation-delay:-${k.x/20}s"><button aria-label="瞄准${k.label}" aria-pressed="false">${keySVG(k.id)}</button><span class="key-name">${k.label}</span></div>`).join('')}<div class="key-target" aria-hidden="true">你的掌心</div></div>${companion('它们只是普通钥匙，被生日筹备小组施了飞行魔法。先仔细看看形状，再把想要的那把召来。')}<div class="wand-bar"><button class="under-button" id="hint">请卢娜提示</button><button class="cast-button" id="cast-accio" aria-label="施放飞来咒召唤选中的钥匙">↝<small>Accio</small></button></div>`,4);app.querySelectorAll('[data-key]').forEach(el=>el.querySelector('button').onclick=()=>{if(busy)return;selected=el.dataset.key;app.querySelectorAll('[data-key]').forEach(x=>{x.classList.toggle('selected',x===el);x.querySelector('button').setAttribute('aria-pressed',String(x===el))});luna(`你瞄准了${choices.find(k=>k.id===selected).label}。现在，试试飞来咒。`)});$('#cast-accio').onclick=()=>{if(busy)return;if(!selected){luna('先轻触一把钥匙，告诉魔杖你想召来哪一把。');return}busy=true;const key=$(`[data-key=${selected}]`);key.classList.add('called');music.chime();$('#cast-accio').disabled=true;later(()=>{if(selected==='silver'){state.key=true;save();success('好奇','银色钥匙落进掌心。<br>认真观察，也是一种魔法。','去打开最后一扇门',()=>go('door'))}else{luna('这把钥匙与锁孔的提示不符。看看颜色和圆环，再试一次。');key.classList.remove('called','selected');key.querySelector('button').setAttribute('aria-pressed','false');selected='';busy=false;$('#cast-accio').disabled=false}},1800)};$('#hint').onclick=()=>luna('找银色的那一把，头部是圆环而不是菱形。')}
function door(){let chosen='lumos',busy=false;frame('room','challenge-stage door-stage center',`${challengeHeading('03 · ALOHOMORA','一扇门，一种新的可能。','这是普通门锁。翻动咒语光球，再轻触锁；也可以使用刚才找到的钥匙。')}<div class="arena"><div class="door-art" id="door-art"><div class="door-panel"></div><button class="lock" id="lock" aria-label="对门锁施放当前选择的咒语">•</button></div><div class="spell-orbs" role="group" aria-label="切换施法咒语">${spells.map(s=>`<button class="spell-orb" data-door-spell="${s.id}" aria-pressed="${s.id===chosen}" aria-label="选择${s.name}">${s.mark}<small>${s.en}</small></button>`).join('')}</div></div>${companion('最后一点困难了。门后有人认真准备着一个惊喜。')}<div class="wand-bar"><button class="under-button" id="use-key">使用银色钥匙 →</button></div>`,5);app.querySelectorAll('[data-door-spell]').forEach(b=>b.onclick=()=>{chosen=b.dataset.doorSpell;app.querySelectorAll('[data-door-spell]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));luna(`魔杖已经准备好：${spells.find(x=>x.id===chosen).name}。轻触门锁试试。`)});const open=()=>{if(busy)return;busy=true;$('#door-art').classList.add('open');$('#lock').disabled=true;$('#use-key').disabled=true;music.chime(true);burst(innerWidth/2,innerHeight/2,'#fff1b4');luna('咔哒。门开了。你看，新的故事正在等你。');later(()=>go('memory'),2300)};$('#lock').onclick=()=>{if(busy)return;if(chosen==='alohomora')open();else{music.chime();if(chosen==='lumos'){impact();luna('锁被照亮了，却还没有打开。换一句能打开普通门锁的咒语。')}else luna('这把锁牢牢装在门上。试试开锁咒，或者你手里的钥匙。')}};$('#use-key').onclick=()=>{if(state.key)open();else luna('还没有拿到钥匙。可以用阿拉霍洞开来打开普通门锁。')}}
function memory(){frame('patronus','memory-stage center',`<div class="memory-scene"><div class="eyebrow">THE ROOM WAS WAITING FOR YOU</div>${hare()}<h1 class="title">跟上那只银色野兔。</h1><p>卢娜的守护神跃过门槛。<br>这一次，有求必应屋把所有灯光，都留给了你。</p><p>想起一个让你觉得被爱着的瞬间。<br>不用说出来，让它在心里亮一下。</p><button class="gold-button" id="remember">我想起来了 · 让灯光亮起 ✧</button></div>`,5);$('#remember').onclick=()=>{state.finished=true;go('final');music.chime(true);celebrate()}}
function final(){const s=spells.find(x=>x.id===state.spell)||spells[0];frame('hall','final-stage center',`<div class="final-content"><div class="eyebrow">THE MAGIC WAS ALWAYS IN YOU</div><div class="final-age">21</div><div class="eyebrow">HAPPY BIRTHDAY · ${who()}</div><h1>愿21岁的你，<br>仍相信世上有魔法。<span>愿这世上最伟大的魔法——爱，<br>始终在你身上应验。</span></h1><p class="subtitle">那些被看见、被理解、被珍爱的时刻，<br>会陪你走向下一个明亮的日子。</p><p class="birthday-letter">愿你像卢娜一样，珍惜自己的与众不同，<br>也始终拥有被理解、被珍爱的幸运。<br>即使偶尔走进迷雾，也有勇气举起魔杖，<br>有朋友与你并肩，有一盏灯为你而亮。<br><strong>二十一岁生日快乐。愿你心里的光，长明不熄。</strong></p><div class="keepsake">${H().name} &nbsp; · &nbsp; ${s.name} &nbsp; · &nbsp; 勇气、好奇与珍爱</div><div class="actions"><button class="gold-button" id="share">寄出这封魔法来信 ↗</button><button class="under-button" id="restart-final">重新开启一段故事</button></div></div>`,6);candles(21);$('#share').onclick=()=>{openDialog('#share-dialog');$('#share-url').value=location.origin+location.pathname};$('#restart-final').onclick=()=>fresh()}
