const canvas=$('#particles'),cx=canvas.getContext('2d');let w=innerWidth,h=innerHeight,dpr=Math.min(devicePixelRatio||1,1.5),sparks=[],raf=0;
const lights=Array.from({length:reduced?8:24},(_,i)=>({x:((i*137.508)%997)/997,y:((i*97.23)%601)/601,r:.5+(i%3)*.4,s:.00006+(i%5)*.00002}));
