function burst(x,y,color='#e8cb8e'){if(reduced)return;for(let i=0;i<34;i++){const a=Math.random()*Math.PI*2,v=1+Math.random()*3;sparks.push({x,y,vx:Math.cos(a)*v,vy:Math.sin(a)*v,life:1,color})}}
let lastFrame=0;
function draw(time=0){if(document.hidden){raf=0;return}if(!reduced&&time-lastFrame<32){raf=requestAnimationFrame(draw);return}lastFrame=time;cx.clearRect(0,0,w,h);lights.forEach(p=>{if(!reduced)p.y=(p.y-p.s+1)%1;cx.globalAlpha=.25+Math.sin(p.x*27+p.y*16)*.16;cx.fillStyle='#e6d8b6';cx.beginPath();cx.arc(p.x*w,p.y*h,p.r,0,Math.PI*2);cx.fill()});sparks=sparks.filter(p=>p.life>0);sparks.forEach(p=>{p.x+=p.vx;p.y+=p.vy;p.vy+=.015;p.life-=.014;cx.globalAlpha=Math.max(0,p.life);cx.fillStyle=p.color;cx.beginPath();cx.arc(p.x,p.y,Math.max(.2,p.life*2),0,Math.PI*2);cx.fill()});cx.globalAlpha=1;if(!reduced)raf=requestAnimationFrame(draw)}draw();
document.addEventListener('visibilitychange',()=>{if(document.hidden){cancelAnimationFrame(raf);raf=0}else if(!reduced&&!raf){lastFrame=0;raf=requestAnimationFrame(draw)}});
let last=0;document.addEventListener('pointermove',e=>{if(reduced||e.pointerType!=='mouse'||Date.now()-last<40)return;last=Date.now();if(sparks.length>100)return;sparks.push({x:e.clientX,y:e.clientY,vx:0,vy:-.4,life:.6,color:'#e0c18b'})});
function celebrate(){if(reduced)return;for(let i=0;i<8;i++)later(()=>burst(w*(.2+Math.random()*.6),h*(.2+Math.random()*.4)),i*300)}
music.ui();


