'use strict';
// Four separate storylines, inspired by canonical scenes; interactions and dialogue are original.
const campaigns={
 gryffindor:{title:'把恐惧变成笑声',sub:'黑魔法防御术教室 → 决斗练习 → 湖畔守护神',inspiration:'《阿兹卡班的囚徒》的博格特课堂、湖畔守护神；《凤凰社》的邓布利多军。',end:'你让恐惧变成笑声，也学会在别人需要时站到前面。卢娜的野兔和你的银光，一起照亮了湖岸。',reward:'勇气与守护',spells:[['riddikulus','滑稽滑稽','Riddikulus','为恐惧添一点荒诞，再用笑声驱散它。','☂'],['expelliarmus','除你武器','Expelliarmus','解除对手的武器；练习中请瞄准魔杖。','↗'],['patronum','呼神护卫','Expecto Patronum','集中于幸福回忆。高阶咒语需要练习，今晚先试着凝成银光。','☽']]},
 hufflepuff:{title:'让温柔长出力量',sub:'曼德拉草温室 → 魔鬼网 → 温室水渠',inspiration:'《密室》的曼德拉草换盆课；《魔法石》电影中的魔鬼网与阳光咒。',end:'你和卢娜救护了幼苗，越过魔鬼网，又让干涸的水渠重新流动。温柔从来不只是一种心情，它是你亲手做过的事情。',reward:'耐心与照料',spells:[['leviosa','羽加迪姆·勒维奥萨','Wingardium Leviosa','使物体漂浮。温室里用它搬动空花盆，不对活的曼德拉草冒险施法。','↟'],['solem','阳光咒','Lumos Solem','电影中的咒语，放出强光，帮助驱退怕光的魔鬼网。','☀'],['aguamenti','清水如泉','Aguamenti','从魔杖尖端召出水流，照料需要水的植物。','≈']]},
 ravenclaw:{title:'看见别人忽略的答案',sub:'鹰环门前 → 星图修复 → 卢娜遗失的鞋',inspiration:'《死亡圣器》的拉文克劳鹰环门；《凤凰社》中卢娜被藏起的物品。星图谜题为原创。',end:'你听懂了门的问题，拼起了星图，也把一双鞋交还给了等待它的人。卢娜说，今晚有人愿意认真帮她找东西，这比猜对谜底更值得记住。',reward:'好奇与理解',spells:[['lumos','荧光闪烁','Lumos','照亮褪色的图纹，先看清，再下结论。','✧'],['reparo','恢复如初','Reparo','修复破损物件；今晚用来修好一张撕裂的普通星图。','◇'],['accio','飞来咒','Accio','明确要召来的物品。找到相配的一双鞋，再把它们召回来。','↝']]},
 slytherin:{title:'越过欲望，作出选择',sub:'魔药准备台 → 七瓶逻辑关 → 厄里斯魔镜',inspiration:'《魔法石》原著的斯内普七瓶逻辑关，与原著及电影中的厄里斯魔镜。这里是无毒、无火墙的课堂重演。',end:'你读出了瓶子之间的逻辑，也懂得镜子只映照渴望。卢娜陪你转身离开镜面，你把通向未来的选择留在了自己手里。',reward:'清醒与决断',spells:[['scourgify','清理一新','Scourgify','清除器具上的污垢，让标签重新可读。','≋'],['incendio','火焰熊熊','Incendio','点燃练习台内的燃料，借烛光观察瓶子。','♨'],['finite','咒立停','Finite Incantatem','终止一般持续咒语；不能随意解除所有强大魔法。','⊘']]}
};
const originalFinal=final;
function campaign(){return campaigns[H().id]}
function installSpells(){const c=campaign();spells.splice(0,spells.length,...c.spells.map(([id,name,en,detail,mark])=>({id,name,en,detail,text:detail,mark,tag:'路线专属'})))}
function branchData(){state.storyStep=Number.isInteger(state.storyStep)?Math.max(0,Math.min(2,state.storyStep)):0;state.routeDone=Array.isArray(state.routeDone)?state.routeDone:[]}
arrival=function(){installSpells();const c=campaign();frame(H().id,'house-stage center',`<div class="house-arrival route-arrival"><div class="eyebrow">${H().en} · THREE CHAPTERS</div><div class="house-letter">${H().letter}</div><h1 class="title">${c.title}</h1><p class="subtitle">${c.sub}</p><p class="route-origin">经典场景灵感 · ${c.inspiration}</p><div class="actions"><button class="gold-button" id="open-book">和卢娜一起准备这趟旅程 →</button></div></div>${companion({gryffindor:'“我也会紧张。”卢娜把练习室的门推开，“我们轮流站在前面。先练笑声，再练保护彼此。”',hufflepuff:'卢娜把两副耳罩放在桌上。“一副给你，一副给我。今天照顾的，是会大声抗议的幼苗。”',ravenclaw:'“我很喜欢不只有一个答案的问题。”卢娜在鹰环前停下，“你来解释，我替你找反例。”',slytherin:'卢娜翻过七张旧笔记。“你检查正面的标签，我来读背面的记录。我们不必把每个闪亮的东西都带走。”'}[H().id])}`,2);$('#open-book').onclick=()=>go('spells')};
spellbook=function(){installSpells();let current=state.spell&&spells.some(s=>s.id===state.spell)?state.spell:spells[0].id;const c=campaign();frame(H().id,'spell-stage center',`${title('YOUR HOUSE · YOUR MAGIC',H().name+'的三句魔法','这趟旅程只使用本路线的魔法。翻页试用，再珍藏你最喜欢的一句。')}<div class="book-wrap"><div class="spellbook"><div class="spell-tabs" role="tablist" aria-label="路线专属咒语">${spells.map(s=>`<button class="spell-tab" role="tab" aria-selected="${s.id===current}" data-route-spell="${s.id}">${s.name}</button>`).join('')}</div><div class="book-page" id="route-page" role="tabpanel"></div><div class="book-page"><div class="route-spell-art" id="route-art"></div><button class="try-spell" id="route-try">与卢娜一起试用 ✧</button></div></div><p class="caption" id="spell-response" role="status">${c.sub}</p><div class="book-actions"><button class="gold-button" id="keep-spell">珍藏这句魔法，出发 →</button></div></div>`,3);function update(){const s=spells.find(x=>x.id===current);$('#route-page').innerHTML=`<small>${H().en} · FIELD NOTES</small><h2>${s.name}</h2><p style="font:italic 20px Georgia;color:#82653c">${s.en}</p><p>${s.detail}</p>`;$('#route-art').innerHTML=`<span class="route-rune">${s.mark}</span><span class="route-art-caption">${s.en}</span>`;app.querySelectorAll('[data-route-spell]').forEach(b=>b.setAttribute('aria-selected',String(b.dataset.routeSpell===current)))}app.querySelectorAll('[data-route-spell]').forEach(b=>b.onclick=()=>{current=b.dataset.routeSpell;update()});$('#route-try').onclick=()=>{music.chime();const s=spells.find(x=>x.id===current);$('#spell-response').textContent='卢娜与你练习了「'+s.name+'」。'+s.detail;const r=$('#route-art').getBoundingClientRect();burst(r.x+r.width/2,r.y+r.height/2);$('#route-art').classList.remove('rune-cast');void $('#route-art').offsetWidth;$('#route-art').classList.add('rune-cast')};$('#keep-spell').onclick=()=>{state.spell=current;state.storyStep=0;state.routeDone=[];go('branch')};update()};
function branchFrame(image,label,t,sub,objects,line,controls='',cls=''){branchData();frame(image,`branch-stage center ${cls}`,`${challengeHeading(label,t,sub)}<div class="branch-board" id="board">${objects}</div>${companion(line)}<div class="branch-controls">${controls}</div><div class="branch-route-tag">${H().name} · ${state.storyStep+1} / 3 · ${campaign().title}</div>`,state.storyStep+3);}
function btn(id,text,cls='gold-button'){return `<button id="${id}" class="${cls}">${text}</button>`}
function stageEnd(title,text){if($('#success-next'))return;state.routeDone.push(title);save();music.chime(true);success(title,text,state.storyStep<2?'与卢娜前往下一幕':'带着这段故事，去赴约',()=>{if(state.storyStep<2){state.storyStep++;go('branch')}else{state.finished=true;go('final');celebrate()}})}
function magic(){music.chime();const r=$('#board').getBoundingClientRect();burst(r.x+r.width/2,r.y+r.height/2)}
function gryffindorBranch(){
 if(state.storyStep===0){let opened=false,costume=false;branchFrame('boggart-v3','I · RIDDIKULUS','先替恐惧，添一点荒诞。','灵感：卢平的博格特课。卢娜看守柜门，你为纸上描绘的蜘蛛挑一副滑稽模样。',`<div class="wardrobe" id="wardrobe"><button id="open-cabinet" aria-label="打开练习柜">H<span>轻触打开</span></button><div class="spider" id="spider" hidden><svg viewBox="0 0 220 160" aria-label="纸上蜘蛛练习影像"><g stroke="currentColor" stroke-width="5" fill="none"><path d="m95 70-45-35-25 20m68 30-50-10-30 20m80 0-45 20-15 30m68-36-23 35 5 23m42-77 45-35 25 20m-48 30 50-10 30 20m-80 0 45 20 15 30m-68-36 23 35-5 23"/></g><ellipse cx="110" cy="88" rx="24" ry="32" fill="currentColor"/><circle cx="110" cy="52" r="19" fill="currentColor"/><g fill="#e9d5a6"><circle cx="103" cy="49" r="3"/><circle cx="117" cy="49" r="3"/></g></svg><div class="skates">◉ ◉ ◉ ◉</div></div></div><button id="give-skates" class="prop-choice" aria-label="给蜘蛛想象一套滚轮溜冰鞋">◉<small>溜冰鞋 · 把它想象在蜘蛛脚下</small></button>`,'卢娜守住柜门：“不用真的放出博格特。我们先对着教材影像练习想象。你来决定，它怎样才会滑稽。”',btn('cast-riddikulus','挥杖 · 滑稽滑稽'));$('#open-cabinet').onclick=()=>{opened=true;$('#open-cabinet').classList.add('ajar');$('#spider').hidden=false;luna('“现在它看起来很可怕。可是，如果八条腿都穿上溜冰鞋呢？”卢娜指向旁边的鞋子。')};$('#give-skates').onclick=()=>{if(!opened){luna('卢娜提醒你：先打开练习柜，看清纸上影像。');return}costume=true;$('#spider').classList.add('costume');luna('卢娜忍不住笑了：“它大概连直线都滑不好。把这幅样子留在脑海里。”')};$('#cast-riddikulus').onclick=()=>{if(!costume){luna('这句咒语需要具体的滑稽想象。先给纸上蜘蛛穿上溜冰鞋。');return}magic();$('#spider').classList.add('spider-skate');later(()=>stageEnd('笑声','纸上的蜘蛛滑了个四脚朝天。卢娜笑出了声，替你记下这一页。<br>真正的博格特需要咒语与笑声驱散；今晚先完成的是想象练习。'),900)}}
 else if(state.storyStep===1){let shield=false;branchFrame('room','II · EXPELLIARMUS','这一次，我们轮流守护。','灵感：邓布利多军。先请卢娜建立防护，再瞄准练习木偶的魔杖。',`<div class="duel-shield" id="duel-shield"></div><button class="luna-cast" id="luna-shield"><img src="assets/luna.webp" alt="施法中的卢娜"><span>请卢娜掩护你</span></button><button class="training-dummy" id="dummy" aria-label="对木偶手中的魔杖施放除你武器"><span class="dummy-head"></span><span class="dummy-body"></span><span class="dummy-wand" id="dummy-wand"></span><small>瞄准魔杖 · 除你武器</small></button>`,'“我先用盔甲护身建立防护。你来解除木偶的武器，练完我们交换位置。”卢娜举起魔杖。', '<span class="control-note">轻触卢娜，再轻触木偶手中的魔杖</span>');$('#luna-shield').onclick=()=>{shield=true;$('#duel-shield').classList.add('shield-up');$('#luna-shield').disabled=true;music.chime();luna('“盔甲护身！”卢娜在你身前展开盾光。“现在，瞄准魔杖，而不是对手的身体。”')};$('#dummy').onclick=()=>{if(!shield){luna('卢娜把你的魔杖轻轻压低：“我们先配合好防护，再开始练习。”');return}$('#dummy').disabled=true;$('#dummy-wand').classList.add('disarmed');magic();later(()=>stageEnd('配合','木偶的魔杖旋转着飞离掌心，卢娜的盾光稳稳挡住练习火花。<br>你没有独自逞强，她也不是只在身旁观看。'),900)}}
 else{let remembered=false,count=0;branchFrame('patronus','III · EXPECTO PATRONUM','你的银光，和她的野兔。','灵感：湖畔守护神。这里没有真正的摄魂怪，只有一场需要耐心的高阶练习。',`<div class="patronus-field" id="patronus-field"><div class="your-light" id="your-light"></div><div class="luna-hare" id="luna-hare" hidden>${hare()}</div><div class="light-caption" id="light-caption">还不成形的银雾，也值得认真练习。</div></div>`, '卢娜没有替你选择快乐。“想起一次真正被爱着的时刻。我会在你旁边施咒，我们一起试。”',btn('recall','把一段幸福回忆放在心里')+btn('patronus-cast','集中意念 · 呼神护卫','line-button'));$('#recall').onclick=()=>{remembered=true;$('#recall').disabled=true;luna('卢娜闭上眼睛，又睁开。“准备好了。我数到三，就和你一起举起魔杖。”')};$('#patronus-cast').onclick=()=>{if(!remembered){luna('“先找回那段回忆。”卢娜放慢语速，“不要急着念咒。”');return}count++;magic();$('#your-light').style.setProperty('--power',count/3);$('#light-caption').textContent=['银雾从杖尖逸出。别放开那段回忆。','光更稳定了。卢娜也举起了魔杖。','银光终于连成一道光幕。'][Math.min(count-1,2)];if(count===2){$('#luna-hare').hidden=false;luna('“呼神护卫！”卢娜的野兔从你身旁跃出。她继续与你一同维持光芒。')}if(count===3){$('#patronus-cast').disabled=true;later(()=>stageEnd('守护','你的守护神尚未凝成动物，却已经发出了稳定的银光。卢娜的野兔在光里跳跃。<br>今晚没有替你确定守护神的形态——那会是未来另一段故事。'),1100)}}}
}
function hufflepuffBranch(){
 if(state.storyStep===0){let yours=false,hers=false,pot=false,repotted=false;branchFrame('greenhouse-v3','I · THE MANDRAKES','把耳罩，先给彼此戴好。','灵感：斯普劳特教授的换盆课。处理曼德拉草必须戴耳罩；今晚操作的是安全课堂模型。',`<div class="greenhouse-table"><button class="earmuff" id="ear-yours">♧<span>你的耳罩</span></button><div class="mandrake-model" id="plant">♧<small>曼德拉草模型 · 卢娜负责扶稳</small></div><button class="earmuff" id="ear-luna">♧<span>卢娜的耳罩</span></button><div class="pot source-pot"></div><button class="pot target-pot" id="target-pot" aria-label="将模型放入新盆"><span>新花盆</span></button></div>`, '卢娜检查着耳罩的软垫：“真正的曼德拉草叫声危险。模型课也要先养成保护彼此的习惯。”',btn('levitate-pot','羽加迪姆·勒维奥萨 · 移来空盆'));function equip(){luna(yours&&hers?'卢娜竖起大拇指。两副耳罩都就位了，可以先移来右边的空花盆。':'还差一副耳罩。卢娜在等你一起准备好。')}$('#ear-yours').onclick=()=>{yours=true;$('#ear-yours').classList.add('equipped');equip()};$('#ear-luna').onclick=()=>{hers=true;$('#ear-luna').classList.add('equipped');equip()};$('#levitate-pot').onclick=()=>{if(!yours||!hers){luna('先给自己和卢娜都戴好耳罩。');return}pot=true;magic();$('#target-pot').classList.add('pot-ready');luna('空盆浮到桌边。卢娜用戴着手套的手扶住模型根部，示意你轻触新盆接住它。')};$('#target-pot').onclick=()=>{if(!pot){luna('新盆还太远。先用漂浮咒把空盆移到手边。');return}if(repotted)return;repotted=true;$('#plant').classList.add('repotted');later(()=>stageEnd('照料','你移好花盆，卢娜扶稳幼苗模型，一起完成了换盆。<br>魔法有时只是让一件细小的事，被认真完成。'),900)}}
 else if(state.storyStep===1){let breaths=0;branchFrame('snare-v3','II · DEVIL’S SNARE','越挣扎，缠得越紧。','灵感：《魔法石》的魔鬼网。模型藤蔓由课堂魔法操控；先停止挣扎，再让光照进来。',`<div class="vines" id="vines">${Array.from({length:7},(_,i)=>`<i style="--i:${i}"></i>`).join('')}<span class="breath-orb" id="breath-orb">慢下来</span></div>`,'卢娜先放松了手臂：“我记得它喜欢阴暗潮湿。先不要用力扯，我会陪你把呼吸放慢。”',btn('breathe','跟随卢娜 · 缓缓呼气')+btn('sunlight','举杖 · Lumos Solem','line-button'));$('#breathe').onclick=()=>{breaths++;$('#breath-orb').textContent=['慢慢吸气','缓缓呼气','松开双手'][Math.min(breaths-1,2)];$('#vines').style.setProperty('--loosen',Math.min(breaths,3));music.chime();if(breaths>=3){$('#breathe').disabled=true;$('#vines').classList.add('relaxed');luna('卢娜的动作和你一起放缓。藤蔓松动了，她转动一片叶子，露出可以照光的缝隙。')}};$('#sunlight').onclick=()=>{if(breaths<3){luna('你还在用力。先跟着卢娜完成三次呼吸，让藤蔓松开。');return}$('#sunlight').disabled=true;$('#vines').classList.add('sunlit');impact();magic();later(()=>stageEnd('从容','强光穿过卢娜留出的叶隙，魔鬼网模型退开。<br>这次你们先找回镇定，再一起找到出口。'),900)}}
 else{let flow=false,turned=false;branchFrame('greenhouse-v3','III · AGUAMENTI','把水，送到真正需要的地方。','温室里三条水渠断开了。卢娜修正出口，你转动中央水闸，再用清水如泉供水。',`<div class="water-garden" id="water-garden"><span class="garden-plant">♧<small>待浇灌的幼苗</small></span><div class="water-channel"></div><button class="water-wheel" id="water-wheel" aria-label="旋转中央水闸">⊗<small>转动水闸</small></button><button class="luna-valve" id="luna-valve">请卢娜扶正出口</button></div>`, '卢娜蹲在水渠尽头。“我扶住这节出口，你来调水闸。等方向一致，再放水，别把幼苗冲倒。”',btn('water','轻轻施法 · 清水如泉'));$('#water-wheel').onclick=()=>{turned=!turned;$('#water-wheel').classList.toggle('aligned',turned);luna(turned?'水闸对正了。再确认卢娜已经扶好出口。':'水闸转偏了。轻触一次，把它重新对正。')};$('#luna-valve').onclick=()=>{flow=true;$('#luna-valve').disabled=true;$('#water-garden').classList.add('held');luna('卢娜扶住末端木槽。她望向你：“好了，水流轻一点。”')};$('#water').onclick=()=>{if(!flow||!turned){luna('水闸和出口还没有同时就位。请卢娜扶好木槽，再转正水闸。');return}$('#water').disabled=true;$('#water-garden').classList.add('watered');magic();later(()=>stageEnd('温柔的力量','水沿着你们接好的水渠流到根边。卢娜扶着木槽，看幼苗一点点挺起叶片。<br>没有战斗的夜晚，也可以有值得铭记的胜利。'),1100)}}
}
function ravenclawBranch(){
 if(state.storyStep===0){let listened=false;branchFrame('ravenclaw','I · THE EAGLE KNOCKER','门，想听见你的解释。','鹰环会提出问题。本题为原创：什么东西，分享之后，你和别人反而拥有得更多？',`<div class="eagle-door"><div class="eagle-ring">◇<span>不是口令，是解释。</span></div><button class="knock" id="knock">叩响鹰环</button></div><div class="riddle-words"><button data-idea="知识">知识 · 因理解而增多</button><button data-idea="快乐">快乐 · 因分享而增多</button><button data-idea="金币">金币 · 因分开而增多</button></div>`, '卢娜歪着头想了想：“我想到快乐。你呢？先敲门，再试着让它听懂你的道理。”',btn('ask-luna','听听卢娜的另一种解释','line-button'));$('#knock').onclick=()=>{listened=true;$('#knock').disabled=true;$('#board').classList.add('awake');luna('鹰环的声音响起：“说出你的答案，也说出理由。”卢娜没有替你作答。')};$('#ask-luna').onclick=()=>luna('卢娜说：“知道有人和你一样快乐，那份快乐就不只在一个人心里了。不过，知识也说得通。”');app.querySelectorAll('[data-idea]').forEach(b=>b.onclick=()=>{if(!listened){luna('先叩响鹰环，让它听见你。');return}if(b.dataset.idea==='金币'){luna('“金币分给别人，数量会减少。”卢娜轻轻说，“想想不因给予而减少的东西。”');return}state.riddleAnswer=b.dataset.idea;$('#board').classList.add('door-answer');magic();stageEnd('独立的答案',`你解释了「${esc(b.dataset.idea)}」为什么会因分享而增多。鹰环认可了你的理由。<br>卢娜微笑：不同答案，也可以因为讲得通而同时成立。`)})}
 else if(state.storyStep===1){let lit=false,angles=[1,2,3,1];branchFrame('ravenclaw-v3','II · REPARO','先理解碎片，才知道怎样相连。','一张普通星图被撕裂。荧光闪烁照出每片的「北 ↑」标记；转正四片，再修复。',`<div class="star-map" id="star-map">${angles.map((a,i)=>`<button data-piece="${i}" style="--turn:${a*90}deg" aria-label="旋转第${i+1}片星图"><span class="north">北 ↑</span><span class="constellation">${['✧—✦','✦ · ✧','✧ ╱ ✦','✦—✧'][i]}</span></button>`).join('')}</div>`, '卢娜稳住窗边飘动的碎纸：“先别急着修复。我扶住碎片，你把北边对正，我们就能读到背面的线索。”',btn('map-lumos','荧光闪烁 · 看清图纹','line-button')+btn('map-reparo','恢复如初 · 连起星图'));$('#map-lumos').onclick=()=>{lit=true;$('#star-map').classList.add('map-lit');magic();luna('光照出了四枚向北的箭头。轻触碎片旋转，直到每个箭头都朝上。')};app.querySelectorAll('[data-piece]').forEach(b=>b.onclick=()=>{if(!lit){luna('图纹太暗。先用荧光闪烁照明。');return}const i=Number(b.dataset.piece);angles[i]=(angles[i]+1)%4;b.style.setProperty('--turn',angles[i]*90+'deg');b.setAttribute('aria-label',`第${i+1}片星图，箭头${['朝上','朝右','朝下','朝左'][angles[i]]}`);b.classList.toggle('aligned',angles[i]===0);music.chime()});$('#map-reparo').onclick=()=>{if(!lit||angles.some(a=>a!==0)){luna('还有碎片没有朝向同一个北方。卢娜仍扶着纸边，等你把四枚箭头都转正。');return}$('#star-map').classList.add('repaired');magic();stageEnd('看清之后再修复','撕口在银光中合拢。卢娜把星图翻过来，发现背面写着：<br>“遗失物招领：窗边架子，蓝色鞋扣。”她认出了那是自己的鞋。')}}
 else{let selected=[],light=false;const pairs=[{id:0,symbol:'♧',color:'copper',name:'棕色短靴'},{id:1,symbol:'◇',color:'blue',name:'蓝扣左鞋'},{id:2,symbol:'✦',color:'red',name:'红扣右鞋'},{id:3,symbol:'◇',color:'blue',name:'蓝扣右鞋'}];branchFrame('ravenclaw','III · ACCIO','这一次，她不必独自等。','线索指向窗边遗失物架。卢娜记得蓝色菱形鞋扣；找出相配的两只鞋，再召回。',`<div class="lost-shoes">${pairs.map(p=>`<button data-shoe="${p.id}" class="shoe ${p.color}" aria-pressed="false" aria-label="${p.name}"><svg viewBox="0 0 100 70" aria-hidden="true"><path d="M15 10h27l7 28 33 8q15 3 9 15H11Z" fill="currentColor"/><text x="28" y="32" font-size="18" fill="#f0e1b9">${p.symbol}</text></svg><small>${p.name}</small></button>`).join('')}</div><div class="returned-shoes" id="returned-shoes" hidden>◇ &nbsp; ◇</div>`, '卢娜指了指自己的袜子：“有时候它们会自己回来。可是今天，你真的帮我找了。”她说得很轻，却很认真。',btn('shoes-light','照亮鞋扣 · Lumos','line-button')+btn('shoes-accio','召回选中的鞋 · Accio'));$('#shoes-light').onclick=()=>{light=true;$('#board').classList.add('shoes-lit');luna('蓝色的菱形鞋扣在光下亮起来。卢娜认出了它们：“对，就是这个形状。”');magic()};app.querySelectorAll('[data-shoe]').forEach(b=>b.onclick=()=>{if(!light){luna('先照亮鞋扣，再检查形状与颜色。');return}const i=Number(b.dataset.shoe);if(selected.includes(i))selected=selected.filter(x=>x!==i);else if(selected.length<2)selected.push(i);else{luna('一双鞋只需要两只。可以先轻触取消选中的那只。');return}b.setAttribute('aria-pressed',String(selected.includes(i)))});$('#shoes-accio').onclick=()=>{if(selected.length!==2||!selected.includes(1)||!selected.includes(3)){luna('卢娜摇摇头：“要两只蓝色菱形鞋扣，一左一右。”再仔细看看。');return}magic();$('#returned-shoes').hidden=false;stageEnd('被认真对待','你说出召唤目标，两只蓝扣鞋飞回卢娜脚边。<br>“谢谢你。”她没有说它们本来就会回来。她知道你做了什么。')}}
}
function slytherinBranch(){
 if(state.storyStep===0){let clean=false,flame=false;branchFrame('slytherin','I · THE PREPARATION TABLE','标签上的灰，不是谜底。','魔药台封存了七只课堂模型瓶。先清洁，再点燃台内蜡烛，请卢娜读取背面的注释。',`<div class="prep-table"><div class="dust-label" id="dust-label"><span>七瓶 · 课堂模型<br>全部无毒，不饮用</span><div class="dust" id="dust">✦ · ░ · ✦ · ░</div></div><div class="practice-flame" id="practice-flame"><i></i><span>封闭烛台</span></div><button class="luna-read" id="luna-read">请卢娜查看背面笔记</button></div>`, '卢娜把手伸到瓶子后面：“有一张被灰盖住的注释。我读背面，你处理标签。先别碰任何瓶塞。”',btn('clean-label','清理一新 · Scourgify','line-button')+btn('light-candle','点燃烛台 · Incendio'));$('#clean-label').onclick=()=>{clean=true;$('#dust').classList.add('cleaned');magic();luna('灰尘褪去。标签说明这只是无毒的逻辑练习，不能按真正魔药饮用。')};$('#light-candle').onclick=()=>{if(!clean){luna('卢娜指向标签：“先把说明读清楚，再使用练习台。”');return}flame=true;$('#practice-flame').classList.add('burning');magic();luna('烛光亮起。卢娜把背面的纸页移到光下，示意你一起读。')};$('#luna-read').onclick=()=>{if(!clean||!flame){luna('纸页仍看不清。先清洁标签，再点燃封闭烛台。');return}stageEnd('读懂条件','卢娜念出注释：“本关重演七瓶逻辑题的形式，不复制原著危险药剂。答案需要你们合读正反两面。”<br>你们把全部规则带到了下一张桌上。')}}
 else if(state.storyStep===1){let clue=false,selected=-1,cleared=false;const sizes=[70,94,60,84,68,104,74];branchFrame('slytherin','II · THE SEVEN BOTTLES','这里依靠逻辑，不靠运气。','灵感：原著斯内普的七瓶关卡。原创谜题：通行瓶有银色瓶颈；不是两端；也不紧邻最高瓶。',`<div class="bottle-row">${sizes.map((h,i)=>`<button class="potion-bottle ${[1,3,5].includes(i)?'silver-neck':''}" data-bottle="${i}" aria-label="第${i+1}瓶，${[1,3,5].includes(i)?'银':'铜'}色瓶颈，${i===5?'最高':'普通高度'}" aria-pressed="false"><span class="bottle-glass" style="height:${h}px"><i></i></span><small>${i+1}</small></button>`).join('')}</div><div class="bottle-clue" id="bottle-clue">你掌握正面三条规则。卢娜正在看背面。</div><div class="seal-ribbon" id="seal-ribbon">封签上的漂浮魔法仍在持续</div>`, '“银色瓶颈的候选不只一个。”卢娜看着瓶后，“先听完我找到的条件，再作决定。”',btn('read-clue','听卢娜补充条件','line-button')+btn('finite-seal','咒立停 · 停止漂浮封签','line-button')+btn('choose-bottle','提交你们选中的瓶子'));$('#read-clue').onclick=()=>{clue=true;$('#bottle-clue').textContent='卢娜的背面注释：通行瓶左侧的瓶子，比右侧的瓶子高。';luna('卢娜逐一比较邻瓶：“第2瓶左邻70、右邻60；第4瓶左邻60、右邻68；第6瓶左邻68、右邻74。”')};$('#finite-seal').onclick=()=>{cleared=true;$('#seal-ribbon').classList.add('seal-still');$('#seal-ribbon').textContent='漂浮封签停止了 · 现在可以检查瓶子';magic()};app.querySelectorAll('[data-bottle]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.bottle);app.querySelectorAll('[data-bottle]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)))});$('#choose-bottle').onclick=()=>{if(!clue||!cleared){luna('先听完卢娜的背面条件，再用咒立停停止持续飘动的封签。');return}if(selected!==1){luna('对照四个条件：银颈、非两端、不邻最高瓶、左邻高于右邻。卢娜的注释排除了第4与第6瓶。再看第2瓶。');return}magic();stageEnd('清醒的判断','你们选出第2瓶，底座亮起通行标记；谁也没有饮用它。<br>你读懂正面的规则，卢娜补齐背面的条件，缺少任何一面都无法确定答案。')}}
 else{let looked=false,lunaSpoke=false;branchFrame('mirror-v3','III · THE MIRROR OF ERISED','镜子，给不了你明天。','灵感：厄里斯魔镜。这里是生日布置中的魔镜主题重演；它不会预言未来，也不能兑现愿望。',`<div class="erised-frame" id="erised-frame"><button id="look-mirror" aria-label="凝视镜中最深的愿望"><span class="mirror-person">♙</span><span id="mirror-text">轻触镜面</span></button></div>`,'卢娜停在镜子旁，没有催促你。“你想在里面看见什么，可以只留在心里。我会在这边等你。”',btn('talk-luna','转向卢娜，听听她的话','line-button')+btn('leave-mirror','背向镜子，选择真实的路'));$('#look-mirror').onclick=()=>{looked=true;$('#erised-frame').classList.add('desire');$('#mirror-text').textContent='想起一个最深的愿望。它不必告诉任何人。';luna('镜光安静地亮着。卢娜没有替你定义成功，也没有说镜中的景象就是未来。')};$('#talk-luna').onclick=()=>{lunaSpoke=true;luna('卢娜看着你：“我也会想见到不在身边的人。可是一直站在这里，就会错过正在等我们的人。”她把通往大礼堂的请柬递还给你。')};$('#leave-mirror').onclick=()=>{if(!looked||!lunaSpoke){luna('先留一点时间看清自己的愿望，再转过身听听卢娜。');return}$('#erised-frame').classList.add('leaving');magic();stageEnd('属于自己的未来','你没有从镜子里拿走任何奖赏。你接过卢娜递来的请柬，与她一起离开。<br>愿望被认真保存，脚步仍然属于你自己。')}}
}
function branch(){installSpells();branchData();({gryffindor:gryffindorBranch,hufflepuff:hufflepuffBranch,ravenclaw:ravenclawBranch,slytherin:slytherinBranch}[H().id])()}
final=function(){installSpells();originalFinal();const c=campaign();$('#stage .subtitle').textContent=c.end;$('.keepsake').textContent=H().name+' · '+(spells.find(s=>s.id===state.spell)?.name||spells[0].name)+' · '+c.reward;}
render=function(){({home,letter,sorting,arrival,spells:spellbook,branch,final}[state.scene]||home)()};
const originalAudioScene=audioScene;
audioScene=function(){if(state.scene==='branch'){music.change(H().id==='gryffindor'?(state.storyStep===2?'discovery':'danger'):H().id==='hufflepuff'?(state.storyStep===1?'danger':'discovery'):H().id==='ravenclaw'?'discovery':state.storyStep===2?'warmth':'danger')}else originalAudioScene()};
// Remove old route snapshots so a restart and a new major version both begin without selections.
try{localStorage.removeItem('birthday-hogwarts-v2')}catch(e){}

