// Pointer Events work for mouse, pen and touch. A tap is always available too.
// Only the ghost moves during a drag, so the original target cannot slip away.
function propDrag(source,target,onDrop){
 let active=null,ghost=null,ignoreClickUntil=0;
 const reset=()=>{if(ghost)ghost.remove();ghost=null;active=null;target.classList.remove('drop-ready');source.classList.remove('draggable-picked')};
 source.addEventListener('pointerdown',e=>{if(e.button!==0||source.disabled)return;active={id:e.pointerId,x:e.clientX,y:e.clientY,moved:false};source.setPointerCapture(e.pointerId)});
 source.addEventListener('pointermove',e=>{if(!active||active.id!==e.pointerId)return;const dx=e.clientX-active.x,dy=e.clientY-active.y;if(!active.moved&&Math.hypot(dx,dy)<8)return;active.moved=true;e.preventDefault();if(!ghost){ghost=source.cloneNode(true);ghost.removeAttribute('id');ghost.querySelectorAll('[id]').forEach(x=>x.removeAttribute('id'));const r=source.getBoundingClientRect();Object.assign(ghost.style,{position:'fixed',left:r.left+'px',top:r.top+'px',width:r.width+'px',height:r.height+'px',margin:'0',transform:'none',pointerEvents:'none',zIndex:'1000',opacity:'.85'});ghost.setAttribute('aria-hidden','true');document.body.appendChild(ghost);source.classList.add('draggable-picked');target.classList.add('drop-ready')}ghost.style.translate=dx+'px '+dy+'px'});
 source.addEventListener('pointerup',e=>{if(!active||active.id!==e.pointerId)return;const moved=active.moved,r=target.getBoundingClientRect(),inside=e.clientX>=r.left-14&&e.clientX<=r.right+14&&e.clientY>=r.top-14&&e.clientY<=r.bottom+14;reset();if(moved){ignoreClickUntil=Date.now()+500;e.preventDefault();if(inside)onDrop();else toast('没有放稳，再拖一次；也可以轻触物件，再轻触目标。')}});
 source.addEventListener('pointercancel',reset);source.addEventListener('lostpointercapture',reset);source.addEventListener('click',e=>{if(Date.now()<ignoreClickUntil){e.preventDefault();e.stopImmediatePropagation()}},true);
 const old=cleanup;cleanup=()=>{reset();old()};
}

// Rebuild the greenhouse as three different physical activities.
hufflepuffBranch=function(){
 if(state.storyStep===0){
  let yours=false,hers=false,pot=false,selected=false,done=false;
  branchFrame('greenhouse-v3','I · HERBOLOGY','把耳罩，先给彼此戴好。','斯普劳特教授的换盆课 · 戴好两副耳罩，移来空盆，再把曼德拉草模型放进去。',`<div class="greenhouse-table"><button class="earmuff" id="ear-yours" aria-pressed="false">${inkArt.earmuffs}<span>你的耳罩</span></button><button class="mandrake-model" id="plant" aria-label="拿起曼德拉草模型，拖到新盆或轻触新盆放入" style="background:none;border:0;padding:0">${inkArt.mandrake}<small id="plant-tip">模型练习 · 卢娜扶着根部</small></button><button class="earmuff" id="ear-luna" aria-pressed="false">${inkArt.earmuffs}<span>卢娜的耳罩</span></button><div class="pot source-pot"></div><button class="pot target-pot" id="target-pot" aria-label="把模型放入新盆"><span>新花盆</span></button></div>`,'卢娜把另一副耳罩递给你：“真正的曼德拉草叫声很危险。模型课也要先保护好彼此。等你拿稳了，我就松手。”',btn('levitate-pot','移来空盆 · Wingardium Leviosa'));
  const equip=(el,other)=>{el.classList.add('equipped');el.setAttribute('aria-pressed','true');luna(other?'卢娜点点头，两副耳罩都戴好了。现在用漂浮咒把空盆移到身边。':'还差一副耳罩。卢娜等你一起准备好。')};
  $('#ear-yours').onclick=()=>{yours=true;equip($('#ear-yours'),hers)};$('#ear-luna').onclick=()=>{hers=true;equip($('#ear-luna'),yours)};
  $('#levitate-pot').onclick=()=>{if(!yours||!hers){toast('先给自己和卢娜戴好耳罩。');luna('她指指耳朵，又指指你。准备工作也很重要。');return}pot=true;$('#target-pot').classList.add('pot-ready');$('#plant-tip').textContent='拖到右边的新盆 · 或轻触拿起';$('#levitate-pot').disabled=true;magic();luna('空盆停在你手边。把模型拖过去；也可以先轻触模型拿起，再轻触新盆。卢娜会帮你扶稳。')};
  $('#plant').onclick=()=>{if(!pot){toast('先戴好耳罩，用漂浮咒移来空盆。');return}selected=true;$('#plant').classList.add('draggable-picked');$('#target-pot').classList.add('drop-ready');$('#plant-tip').textContent='你已拿稳 · 轻触新盆放下'};
  const repot=()=>{if(done)return;if(!pot){toast('空盆还没到位，先完成准备。');return}done=true;const plant=$('#plant'),target=$('#target-pot'),board=$('.greenhouse-table'),r=target.getBoundingClientRect(),br=board.getBoundingClientRect();Object.assign(plant.style,{left:r.left-br.left+(r.width-plant.offsetWidth)/2+'px',top:r.top-br.top-plant.offsetHeight+45+'px'});plant.disabled=true;plant.classList.add('repotted');target.classList.remove('drop-ready');$('#plant-tip').textContent='卢娜接稳了幼苗';magic();luna('“接住了。”卢娜用手扶住模型，你把松软的土轻轻拢好。');later(()=>stageEnd('照料','你搬好花盆，卢娜扶稳幼苗。那双被你保护好的手，和那株被认真安放的小小植物，都记得这一刻。'),950)};
  $('#target-pot').onclick=()=>{if(!selected){toast(pot?'先轻触模型拿稳，再放进新盆；也可直接拖动模型。':'先移来空盆。');return}repot()};propDrag($('#plant'),$('#target-pot'),repot);
 }else if(state.storyStep===1){
  let breaths=0,busy=false;
  branchFrame('snare-v3','II · DEVIL’S SNARE','越挣扎，缠得越紧。','《魔法石》里的魔鬼网 · 跟随卢娜把呼吸放慢，再用阳光咒驱散阴影。',`<div class="vines" id="vines">${Array.from({length:7},(_,i)=>`<i style="--i:${i}"></i>`).join('')}<span class="breath-orb" id="breath-orb">慢下来</span><span class="breath-instruction" id="breath-instruction">不必拼手速。让呼吸领着你走。</span></div>`,'卢娜先松开双手：“它喜欢阴暗潮湿。别再扯了，看着我，我们慢慢吸气，再慢慢呼气。”',btn('breathe','与卢娜一起呼吸 · 0 / 3')+btn('sunlight','照进阳光 · Lumos Solem','line-button'));
  $('#breathe').onclick=()=>{if(busy||breaths>=3)return;busy=true;const orb=$('#breath-orb');$('#breathe').disabled=true;orb.classList.add('inhale');orb.textContent='慢慢吸气';$('#breath-instruction').textContent='卢娜也在呼吸。藤蔓停止收紧了。';later(()=>{orb.classList.remove('inhale');orb.textContent='缓缓呼气'},900);later(()=>{breaths++;busy=false;$('#breathe').textContent=`与卢娜一起呼吸 · ${breaths} / 3`;$('#vines').style.setProperty('--loosen',breaths);if(breaths<3){$('#breathe').disabled=false;orb.textContent='再来一次'}else{$('#vines').classList.add('relaxed');orb.textContent='松开了';$('#breath-instruction').textContent='叶隙露出来了。现在，把光照进去。';luna('卢娜陪你完成第三轮呼吸，慢慢转开一片叶子：“你看，这里有一条光能进去的缝。”')}},1800)};
  $('#sunlight').onclick=()=>{if(breaths<3){toast('先跟着卢娜完成三轮呼吸，让藤蔓松开。');return}$('#sunlight').disabled=true;$('#vines').classList.add('sunlit');magic();later(()=>stageEnd('从容','光穿过卢娜留出的叶隙，魔鬼网课堂模型退开。你们先找到镇定，再一起找到出口。'),950)};
 }else{
  let held=false,done=false,angles=[1,3,1];
  branchFrame('greenhouse-v3','III · AGUAMENTI','把水，送到需要的地方。','温室的水渠断开了 · 转动三节铜管，让开口全部连成横线。卢娜会替你扶住出口。',`<div class="water-garden" id="water-garden"><span class="garden-plant">${inkArt.plant}<small>等待浇灌的幼苗</small></span><span class="pipe-tip">轻触铜管转动 · 三节都横向才通水</span><div class="water-channel"></div><button class="water-wheel" id="water-wheel" aria-label="查看水闸状态">${inkArt.wheel}<small>水闸</small></button><div class="pipe-set">${angles.map((a,i)=>`<button class="pipe-piece" data-pipe="${i}" aria-pressed="false" aria-label="转动第${i+1}节铜管，当前竖向"><svg viewBox="0 0 80 80" style="transform:rotate(${a*90}deg)"><path d="M3 40h74" stroke="#61482d" stroke-width="24"/><path d="M3 37h74" stroke="#b9975d" stroke-width="17"/><path d="M4 32h72" stroke="#ddc18c" stroke-width="3"/><path d="M9 25v28m62-28v28" stroke="#bca06d" stroke-width="7"/></svg><small>第 ${i+1} 节</small></button>`).join('')}</div><button class="luna-valve" id="luna-valve">请卢娜扶住出口</button></div>`,'“我扶这边，你接那边。”卢娜把木槽稳在幼苗旁。“先对齐水管，再用一点点水。根也需要呼吸。”',btn('water','轻轻施法 · 清水如泉'));
  app.querySelectorAll('[data-pipe]').forEach(b=>b.onclick=()=>{const i=+b.dataset.pipe;angles[i]=(angles[i]+1)%4;b.querySelector('svg').style.transform=`rotate(${angles[i]*90}deg)`;b.setAttribute('aria-pressed',String(angles[i]%2===0));b.setAttribute('aria-label',`转动第${i+1}节铜管，当前${angles[i]%2?'竖':'横'}向`);music.chime();luna(angles.every(a=>a%2===0)?'“接通了！”卢娜检查了每道接缝。“再看看出口，然后放水吧。”':'铜管转过半圈。把每一节的两端都对到左右两侧。')});
  $('#water-wheel').onclick=()=>toast(angles.every(a=>a%2===0)?'三节铜管都已经接通。':'先轻触三节铜管，让开口左右相通。');
  $('#luna-valve').onclick=()=>{held=true;$('#luna-valve').disabled=true;$('#luna-valve').textContent='卢娜扶稳了 · 可以放水';$('#water-garden').classList.add('held');luna('卢娜握住末端木槽：“我这里好了。你那边准备好，就让水流过来。”')};
  $('#water').onclick=()=>{if(done)return;if(!held||angles.some(a=>a%2!==0)){toast(!held?'请卢娜扶住出口，水才不会流到地上。':'还有铜管竖着。先把三节开口都接成横线。');return}done=true;$('#water').disabled=true;$('#water-garden').classList.add('watered');music.chime();magic();later(()=>stageEnd('温柔的力量','水沿着你们亲手接好的铜管流到根边。幼苗慢慢舒展叶片，卢娜终于松开了手。温柔也能做成一件很有力量的事。'),1500)};
 }
};

// Enhance the other nine chapters while keeping their separate stories intact.
const drawBranch=branch;
branch=function(){
 drawBranch();
 $('#stage').dataset.house=H().id;
 const sceneNotes={gryffindor:['卢娜按住旧柜门。先看看教材里的蜘蛛，再替它添上那副会让人发笑的溜冰鞋。','有求必应屋里，练习木偶举起魔杖。先让卢娜掩护你，再瞄准它手中的魔杖。','湖面很冷。把一段幸福回忆放在心里，让你的银光和卢娜的野兔一同亮起。'],ravenclaw:['鹰环问：什么东西，分享之后，你和别人反而拥有得更多？答案不止一个，但要说得通。','风吹散了窗边的星图。先照亮四枚「北 ↑」标记，再转正碎片，让整张图重新相连。','星图背面的线索指向窗边。卢娜记得蓝色菱形鞋扣；找出一左一右，再把鞋召回。'],slytherin:['七只瓶子，一张蒙尘的标签。你收拾桌面，卢娜负责读背面那些褪色的字。','斯内普留下三个条件：银色瓶颈、不在两端、不紧邻最高瓶。最后一条线索，在卢娜手里。','它映照最深的渴望，却无法给出明天。卢娜站在镜子旁，等你决定是否转身。']};
 if(sceneNotes[H().id])$('.challenge-title .subtitle').textContent=sceneNotes[H().id][state.storyStep];

 if($('#give-skates')){const fitSkates=$('#give-skates').onclick;$('#give-skates').innerHTML=inkArt.skates+'<small>溜冰鞋<br>轻触搭配 · 或拖到蜘蛛身上</small>';$('#give-skates').style.touchAction='none';propDrag($('#give-skates'),$('#wardrobe'),()=>fitSkates())}
 if($('#eagle-ring'))$('#eagle-ring').innerHTML=inkArt.eagle; // Older snapshots may not contain this id.
 if($('.eagle-ring'))$('.eagle-ring').innerHTML=inkArt.eagle+'<span>不是口令，是解释。</span>';
 if($('.mirror-person'))$('.mirror-person').innerHTML=inkArt.person;
 if($('.bottle-row')){const heights=[70,94,60,84,68,104,74];app.querySelectorAll('[data-bottle]').forEach((b,i)=>{b.setAttribute('aria-label',`第${i+1}瓶，${[1,3,5].includes(i)?'银':'铜'}色瓶颈，高度${heights[i]}`);b.querySelector('small').insertAdjacentHTML('beforeend',`<span class="bottle-measure">${heights[i]}</span>`)});$('.bottle-row').setAttribute('aria-label','七只魔药瓶，小屏幕可横向滑动查看');$('#board').insertAdjacentHTML('beforeend','<span class="bottle-scroll-hint">瓶下小字是高度<span> · 左右滑动查看七瓶</span></span>');}
 if($('#star-map')){
  app.querySelectorAll('[data-piece]').forEach((b,i)=>{b.innerHTML=`<div class="map-leaf">${b.innerHTML}</div><span class="piece-number">${['I','II','III','IV'][i]}</span>`;const handler=b.onclick;b.onclick=e=>{handler(e);$('#map-progress').textContent=`${app.querySelectorAll('[data-piece].aligned').length} / 4 片已朝北`;b.setAttribute('aria-pressed',String(b.classList.contains('aligned')))}});
  $('#board').insertAdjacentHTML('beforeend','<div class="map-progress" id="map-progress" role="status">先照亮星图，再转动四片纸页。</div>');
 }
 if($('#dust')){
  $('.dust-label>span').innerHTML='斯内普的笔记<br>先辨清，再选择';
  let swipes=0,lastX=0;const dust=$('#dust'),clean=$('#clean-label').onclick;dust.innerHTML='<span style="font:15px/2 var(--serif);padding:20px">拂去这里的积灰<br>左右擦拭 · 或用清理一新</span>';
  dust.onpointerdown=e=>{lastX=e.clientX;dust.setPointerCapture(e.pointerId)};dust.onpointermove=e=>{if(!dust.hasPointerCapture(e.pointerId))return;const distance=Math.abs(e.clientX-lastX);if(distance>16){swipes+=distance;lastX=e.clientX;dust.style.opacity=Math.max(.1,1-swipes/220);if(swipes>=190){clean();dust.style.pointerEvents='none';dust.releasePointerCapture(e.pointerId)}}};
  dust.onclick=()=>{swipes+=70;dust.style.opacity=Math.max(.1,1-swipes/220);if(swipes>=190){clean();dust.style.pointerEvents='none'}};
 }
 if($('#patronus-cast')){
  const button=$('#patronus-cast'),cast=button.onclick;let started=0,charging=false,timer=0,complete=false,suppress=false;
  button.classList.add('cast-hold');button.innerHTML='<span>按住魔杖 · 呼神护卫</span>';button.setAttribute('aria-label','按住约两秒，或轻触三次施放呼神护卫');$('.light-caption').textContent='按住魔杖凝聚银光 · 也可以轻触三次';
  const end=()=>{charging=false;cancelAnimationFrame(timer);if(!complete)button.style.setProperty('--held',0)};
  const tick=()=>{if(!charging)return;const power=Math.min(1,(performance.now()-started)/2200);button.style.setProperty('--held',power);$('#your-light').style.setProperty('--power',power);if(power>=1){complete=true;suppress=true;end();for(let i=0;i<3;i++)cast();return}timer=requestAnimationFrame(tick)};
  button.onpointerdown=e=>{if(!$('#recall').disabled||button.disabled)return;started=performance.now();charging=true;button.setPointerCapture(e.pointerId);timer=requestAnimationFrame(tick)};
  button.onpointerup=end;button.onpointercancel=end;button.onlostpointercapture=end;button.onclick=e=>{if(suppress){suppress=false;return}cast(e)};const old=cleanup;cleanup=()=>{end();old()};
 }
 // Local feedback stays visible when a choice is out of order.
 app.querySelectorAll('.branch-controls button').forEach(b=>{const handler=b.onclick;if(!handler)return;b.onclick=e=>{const before=$('#luna-line')?.textContent;handler(e);if(before!==$('#luna-line')?.textContent&&!$('#success-next')&&!b.disabled&&/先|还没有|还有|再看|再仔细|需要|仍看不清/.test($('#luna-line').textContent))toast($('#luna-line').textContent.replace(/^卢娜[^：“]*[：“]/,'').slice(0,72))}});
};

// Make the spellbook itself a small, forgiving wand exercise.
const oldHome=home;
home=function(){oldHome();$('.hero-copy .small-note').textContent='戴上耳机，在烛光里拆信、挥杖、与卢娜同行。'};
const oldSpellbook=spellbook;
spellbook=function(){
 oldSpellbook();const art=$('#route-art');
 art.insertAdjacentHTML('afterend','<div class="spell-gesture" id="spell-gesture" role="img" aria-label="可用手指或鼠标描画的练习轨迹，也可以用下方按钮试咒"><svg viewBox="0 0 220 100"><path d="M20 75Q80 8 125 48T201 22"/><path class="trace" id="wand-trace" d=""/><circle cx="20" cy="75" r="5" fill="#9f6639"/><path d="m195 18 9 1-3 9" stroke="#8f7147" fill="none"/></svg></div><p class="gesture-caption" id="gesture-caption">沿墨线挥杖；也可轻触下方按钮试咒。</p>');
 const panel=$('#spell-gesture');let points=[],active=false,length=0;const coordinate=e=>{const r=panel.getBoundingClientRect();return [(e.clientX-r.left)/r.width*220,(e.clientY-r.top)/r.height*100]};
 panel.onpointerdown=e=>{if(e.button!==0)return;active=true;length=0;points=[coordinate(e)];panel.setPointerCapture(e.pointerId);$('#wand-trace').setAttribute('d','')};
 panel.onpointermove=e=>{if(!active)return;const p=coordinate(e),last=points[points.length-1];const delta=Math.hypot(p[0]-last[0],p[1]-last[1]);if(delta<2||points.length>=160)return;length+=delta;points.push(p);$('#wand-trace').setAttribute('d',points.map((p,i)=>(i?'L':'M')+p.join(' ')).join(''))};
 panel.onpointerup=()=>{if(!active)return;active=false;if(length>85){$('#route-try').click();$('#gesture-caption').textContent='卢娜看见杖尖亮起，笑着示意你继续。'}else $('#gesture-caption').textContent='再挥得长一些，从墨线一端划到另一端；或直接轻触试咒。'};panel.onpointercancel=()=>{active=false};
 // Replace a giant glowing rune with the sketch-sized exercise.
 art.style.height='80px';art.querySelector('.route-rune').style.fontSize='40px';art.querySelector('.route-art-caption').style.fontSize='11px';
 const tabs=[...app.querySelectorAll('[data-route-spell]')];tabs.forEach((b,i)=>{b.id='route-tab-'+i;b.setAttribute('aria-controls','route-page');b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const j=e.key==='Home'?0:e.key==='End'?2:(i+(e.key==='ArrowRight'?1:2))%3;tabs[j].click();tabs[j].focus()}});
};

// Official player embeds and publisher-hosted preview. No film or novel is rehosted.
const films=[
 {id:'8k2bj-R9m8E',name:'初见卢娜',film:'《哈利·波特与凤凰社》',image:'luna-choice-2'},
 {id:'z4K2F_OALPQ',name:'分院仪式',film:'《哈利·波特与魔法石》',image:'hall'}
];
const bookPreview='https://kids.scholastic.com/content/dam/scholastic/kids/pdf/Book%20Excerpts/HarryPotterSorcersStone_Excerpt.pdf';
let filmIndex=0,resumeAfterLibrary=false;
document.querySelector('.top-actions').insertAdjacentHTML('afterbegin','<button class="library-button" id="open-library" aria-label="打开放映与书房"><span class="library-full">放映与书房</span><span class="library-short">书房</span></button>');
document.body.insertAdjacentHTML('beforeend',`<dialog id="library-dialog" class="dialog library-dialog" aria-labelledby="library-title"><button class="close-panel" id="close-library" aria-label="关闭书房，回到冒险">×</button><div class="eyebrow" style="color:#8a6538">A QUIET CORNER OF THE CASTLE</div><h2 class="library-heading" id="library-title">城堡里，留一会儿。</h2><p class="library-intro">放下魔杖。看看那些让魔法被记住的瞬间，再翻开故事的第一页。</p><div class="library-tabs" role="tablist" aria-label="放映与阅读"><button id="film-tab" role="tab" aria-selected="true" aria-controls="film-pane">经典放映</button><button id="read-tab" role="tab" aria-selected="false" aria-controls="read-pane">烛光书房</button></div><section id="film-pane" role="tabpanel" aria-labelledby="film-tab"><div class="film-layout"><div><div class="film-screen" id="film-screen"></div><a class="media-external" id="film-external" target="_blank" rel="noreferrer">在官方频道打开此片段 ↗</a></div><div class="film-list">${films.map((f,i)=>`<button class="film-option" data-film="${i}" aria-pressed="${i===0}">${f.name}<small>${f.film}<br>Harry Potter 官方频道</small></button>`).join('')}</div></div><p class="media-note">点播放后载入 YouTube 官方播放器；可在播放器中选择字幕。若当前网络不能播放，请使用上方的官方入口，或去书房读一会儿。关闭这里即可回到刚才的冒险。</p></section><section id="read-pane" role="tabpanel" aria-labelledby="read-tab" hidden><div class="book-shelf"><div class="reading-book" aria-hidden="true"><small>J. K. ROWLING</small>Harry<br>Potter<small>THE FIRST CHAPTER</small></div><div class="reading-copy"><h3>一切，开始于一个普通的早晨。</h3><p>《哈利·波特与魔法石》英文原著试读。<br>来自 Scholastic 出版社公开提供的 25 页节选，含第一章。把故事交还给书页，慢慢读。</p><button class="gold-button" id="read-preview">翻开出版社试读本</button><a class="reading-link" href="${bookPreview}" target="_blank" rel="noreferrer">在新窗口阅读英文试读 PDF ↗</a><div class="study-slip"><a class="reading-link" href="https://www.harrypotter.com/features/philosophers-stone-extract-week-three" target="_blank" rel="noreferrer">听 Stephen Fry 读霍格沃茨 · 官方英文原著选段 ↗</a><p class="media-note">这是出版社授权公开的试读入口；正文在出版社页面呈现。本站的中文对白与关卡故事为原创生日同人。</p></div></div></div><div id="reader-mount"></div></section></dialog>`);
const library=$('#library-dialog');
function filmPoster(){const f=films[filmIndex];$('#film-screen').innerHTML=`<img src="assets/${f.image}.webp" alt="${f.name}的官方电影剧照"><button class="film-play" id="play-film" aria-label="播放${f.name}官方片段"><b aria-hidden="true">▶</b><span>放映 · ${f.name}</span></button>`;$('#film-external').href='https://www.youtube.com/watch?v='+f.id;app;document.querySelectorAll('[data-film]').forEach(b=>b.setAttribute('aria-pressed',String(+b.dataset.film===filmIndex)));$('#play-film').onclick=()=>{$('#film-screen').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${f.id}?autoplay=1&rel=0&playsinline=1" title="${f.name} — Harry Potter 官方片段" allow="autoplay; encrypted-media; picture-in-picture; fullscreen" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`}}
$('#open-library').onclick=()=>{resumeAfterLibrary=music.on;if(resumeAfterLibrary)music.disable();$('#music-panel').hidden=true;$('#music-toggle').setAttribute('aria-expanded','false');filmPoster();openDialog('#library-dialog')};$('#close-library').onclick=()=>library.close();library.addEventListener('close',()=>{$('#film-screen').innerHTML='';$('#reader-mount').innerHTML='';if(resumeAfterLibrary)music.enable();resumeAfterLibrary=false;$('#open-library').focus()});document.querySelectorAll('[data-film]').forEach(b=>b.onclick=()=>{filmIndex=+b.dataset.film;filmPoster()});
function libraryTab(read){$('#film-tab').setAttribute('aria-selected',String(!read));$('#read-tab').setAttribute('aria-selected',String(read));$('#film-pane').hidden=read;$('#read-pane').hidden=!read;if(read)$('#film-screen').innerHTML='';else filmPoster()}
$('#film-tab').onclick=()=>libraryTab(false);$('#read-tab').onclick=()=>libraryTab(true);[$('#film-tab'),$('#read-tab')].forEach((b,i)=>b.onkeydown=e=>{if(['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const read=e.key==='Home'?false:e.key==='End'?true:i===0;libraryTab(read);$(read?'#read-tab':'#film-tab').focus()}});
$('#read-preview').onclick=()=>{$('#reader-mount').innerHTML=`<p class="reader-note">若下方没有显示书页，可点上方“在新窗口阅读”。</p><iframe class="reader-frame" src="${bookPreview}#page=9&view=FitH" title="Scholastic 出版社提供的英文原著试读"></iframe>`;$('#reader-mount').scrollIntoView({behavior:reduced?'instant':'smooth',block:'start'})};

// Stronger semantics for the full-screen chapter-completion dialog.
const oldSuccess=success;
success=function(...args){oldSuccess(...args);const panel=$('.success-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.querySelector('h2').id='chapter-complete';panel.setAttribute('aria-labelledby','chapter-complete');const inertNodes=[...$('#stage').children].filter(el=>el!==panel);inertNodes.forEach(el=>el.inert=true);$('.topbar').inert=true;const old=cleanup;cleanup=()=>{$('.topbar').inert=false;old()};panel.onkeydown=e=>{if(e.key==='Tab'){e.preventDefault();$('#success-next').focus()}}};

// A v4 visitor can still continue v3 saves; a fresh start carries no marks.
document.documentElement.dataset.edition='candlelight-v5';
$('#about-dialog').insertAdjacentHTML('beforeend','<p>放映室内嵌 Harry Potter 官方频道的<a href="https://www.youtube.com/watch?v=8k2bj-R9m8E" target="_blank" rel="noreferrer">初见卢娜</a>与<a href="https://www.youtube.com/watch?v=z4K2F_OALPQ" target="_blank" rel="noreferrer">分院仪式</a>片段；原著书房连接<a href="'+bookPreview+'" target="_blank" rel="noreferrer">Scholastic 出版社公开的英文试读</a>。视频、原著正文均由原平台提供，本站不保存电影或原著副本。新增道具插画为本站绘制。</p>');
